// ─── BadgeCard ────────────────────────────────────────────────────────────
function BadgeCard({ badge, FONT }) {
  const { img, title, cur, req, state } = badge;
  const pct     = Math.min((cur / req) * 100, 100);
  const locked  = state === "locked";
  const unlocked= state === "unlocked";

  return (
    <div style={{
      width: 88,
      flexShrink: 0,
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "flex-start",
      gap: 5,
      padding: "10px 4px 8px",
      borderRadius: 16,
      cursor: "pointer",
      background: unlocked
        ? "linear-gradient(180deg,rgba(37,99,235,.07),rgba(124,58,237,.04))"
        : locked ? "rgba(248,250,252,.9)" : "rgba(241,245,249,.95)",
      border: unlocked
        ? "1px solid rgba(124,58,237,.18)" : "1px solid rgba(0,0,0,.05)",
      boxShadow: unlocked ? "0 4px 14px rgba(124,58,237,.1)" : "0 1px 3px rgba(0,0,0,.04)",
    }}>
      {/* Zone image fixe 64×64 — centrée avec flex */}
      <div style={{
        width: 64,
        height: 64,
        flexShrink: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        position: "relative",
      }}>
        {unlocked && (
          <div style={{
            position: "absolute", inset: -5, borderRadius: "50%",
            background: "radial-gradient(circle,rgba(124,58,237,.25) 0%,transparent 70%)",
            pointerEvents: "none",
          }}/>
        )}
        <img
          src={img}
          alt={title}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "contain",
            objectPosition: "center",
            display: "block",
            filter: locked
              ? "grayscale(1) brightness(.35) opacity(.5)"
              : unlocked
              ? "drop-shadow(0 0 7px rgba(124,58,237,.6)) brightness(1.05)"
              : "drop-shadow(0 2px 4px rgba(0,0,0,.15))",
          }}
        />
        {/* Pip état */}
        <div style={{
          position: "absolute", bottom: -1, right: -1,
          width: 17, height: 17, borderRadius: "50%",
          background: unlocked
            ? "linear-gradient(135deg,#22C55E,#15803D)"
            : locked ? "rgba(30,41,59,.85)" : "transparent",
          display: "flex", alignItems: "center", justifyContent: "center",
          border: unlocked ? "1.5px solid #fff" : "none",
          boxShadow: unlocked ? "0 1px 4px rgba(22,163,74,.4)" : "none",
        }}>
          {unlocked && (
            <svg width="8" height="8" viewBox="0 0 12 12" fill="none">
              <path d="M2.5 6.5l2.5 2.5 4.5-5" stroke="white" strokeWidth="2.2"
                strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          )}
          {locked && (
            <svg width="7" height="8" viewBox="0 0 10 12" fill="none">
              <rect x="1" y="5.5" width="8" height="6.5" rx="1.5" fill="#94A3B8"/>
              <path d="M3 5.5V3.5a2 2 0 014 0v2" stroke="#94A3B8" strokeWidth="1.5" fill="none"/>
            </svg>
          )}
        </div>
      </div>

      {/* Titre */}
      <span style={{
        fontSize: 9.5,
        fontWeight: 700,
        textAlign: "center",
        color: locked ? "#94A3B8" : "#0F1629",
        lineHeight: 1.25,
        fontFamily: FONT,
        maxWidth: 80,
        display: "-webkit-box",
        WebkitLineClamp: 2,
        WebkitBoxOrient: "vertical",
        overflow: "hidden",
      }}>{title}</span>

      {/* Progression */}
      {unlocked ? (
        <span style={{ fontSize: 8.5, color: "#22C55E", fontWeight: 700, fontFamily: FONT }}>
          ✓ Débloqué
        </span>
      ) : (
        <div style={{ width: "100%", padding: "0 2px" }}>
          <div style={{
            height: 3, borderRadius: 999, overflow: "hidden",
            background: locked ? "rgba(0,0,0,.07)" : "#E2E8F0",
          }}>
            <div style={{
              width: `${pct}%`, height: "100%", borderRadius: 999,
              background: locked ? "#CBD5E1" : "linear-gradient(90deg,#2563EB,#7C3AED)",
            }}/>
          </div>
          <span style={{
            fontSize: 8, display: "block", textAlign: "center", marginTop: 2,
            fontFamily: FONT, color: locked ? "#CBD5E1" : "#6B7280",
          }}>{cur}/{req}</span>
        </div>
      )}
    </div>
  );
}

// ─── BadgeSection ─────────────────────────────────────────────────────────
const BADGE_CATS = [
  { id: "all",       label: "Tous" },
  { id: "unlocked",  label: "✅ Faits" },
  { id: "available", label: "🔄 En cours" },
  { id: "training",  label: "💪 Training" },
  { id: "nutrition", label: "🥗 Nutrition" },
  { id: "legendary", label: "⭐ Légende" },
];

function BadgeSection({ FONT }) {
  const [cat, setCat] = useState("all");

  const filtered = BADGE_DATA.filter(b =>
    cat === "all"       ? true :
    cat === "unlocked"  ? b.state === "unlocked"  :
    cat === "available" ? b.state === "available" :
    cat === "legendary" ? b.cat   === "legendary" :
    b.cat === cat
  );

  const unlockedCount = BADGE_DATA.filter(b => b.state === "unlocked").length;
  const total         = BADGE_DATA.length;

  return (
    <div style={{ marginBottom: 24 }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <div>
          <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: "0.08em",
            textTransform: "uppercase", color: "#94A3B8", fontFamily: FONT, marginBottom: 4 }}>
            Récompenses
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 9 }}>
            <span style={{ fontSize: 20, fontWeight: 700, color: "#0F1629",
              fontFamily: FONT, letterSpacing: -0.5 }}>Mes Badges</span>
            <span style={{
              fontSize: 11, fontWeight: 700, color: "#fff",
              background: "linear-gradient(135deg,#7C3AED,#2563EB)",
              borderRadius: 10, padding: "2px 9px",
            }}>{unlockedCount}/{total}</span>
          </div>
        </div>
        <button style={{ border: "none", background: "transparent",
          cursor: "pointer", color: "#2563EB", fontWeight: 600,
          fontSize: 13, fontFamily: FONT }}>
          Voir tout
        </button>
      </div>

      {/* Barre de progression globale */}
      <div style={{ marginBottom: 14 }}>
        <div style={{ height: 4, background: "#E8EDF3", borderRadius: 3, overflow: "hidden", marginBottom: 4 }}>
          <div style={{
            width: `${(unlockedCount/total)*100}%`, height: "100%",
            background: "linear-gradient(90deg,#7C3AED,#2563EB,#06B6D4)", borderRadius: 3,
          }}/>
        </div>
        <span style={{ fontSize: 9.5, color: "#94A3B8", fontFamily: FONT }}>
          {Math.round((unlockedCount/total)*100)}% débloquée · {total-unlockedCount} badges restants
        </span>
      </div>

      {/* Filtre chips */}
      <div style={{
        display: "flex", gap: 7, overflowX: "auto",
        paddingBottom: 10, scrollbarWidth: "none",
        WebkitOverflowScrolling: "touch",
      }}>
        {BADGE_CATS.map(c => (
          <button key={c.id} onClick={() => setCat(c.id)} style={{
            flexShrink: 0, padding: "5px 13px", borderRadius: 20,
            border: "none", cursor: "pointer",
            fontSize: 10, fontWeight: 700, fontFamily: FONT,
            background: cat === c.id
              ? "linear-gradient(135deg,#7C3AED,#2563EB)" : "#fff",
            color: cat === c.id ? "#fff" : "#6B7280",
            boxShadow: cat === c.id
              ? "0 3px 10px rgba(124,58,237,.3)" : "0 1px 4px rgba(0,0,0,.07)",
          }}>{c.label}</button>
        ))}
      </div>

      {/* Carousel badges */}
      <div style={{
        display: "flex", gap: 8,
        overflowX: "auto", paddingBottom: 4, paddingTop: 4,
        scrollbarWidth: "none", WebkitOverflowScrolling: "touch",
        alignItems: "stretch",
      }}>
        {filtered.map(b => <BadgeCard key={b.id} badge={b} FONT={FONT}/>)}
      </div>

      {/* Teaser prochain légendaire */}
      <div style={{
        marginTop: 14,
        background: "linear-gradient(135deg,#0F0A1E,#1C1038)",
        borderRadius: 18, padding: "14px 16px",
        display: "flex", alignItems: "center", gap: 12,
        position: "relative", overflow: "hidden",
        boxShadow: "0 4px 20px rgba(0,0,0,.2)",
      }}>
        <div style={{
          position: "absolute", top: -18, right: -8, width: 90, height: 90,
          borderRadius: "50%",
          background: "radial-gradient(circle,rgba(245,158,11,.2) 0%,transparent 70%)",
        }}/>
        {/* Badge mode légende */}
        <div style={{
          width: 52, height: 52, flexShrink: 0,
          display: "flex", alignItems: "center", justifyContent: "center",
          background: "linear-gradient(135deg,#78350F,#D97706,#FDE68A)",
          borderRadius: "50%", boxShadow: "0 3px 16px rgba(245,158,11,.5)",
          overflow: "hidden",
        }}>
          <img
            src={BADGE_DATA.find(b => b.id === "mode_legende")?.img}
            alt="Mode Légende"
            style={{ width: "100%", height: "100%", objectFit: "contain", objectPosition: "center" }}
          />
        </div>
        <div style={{ flex: 1, zIndex: 1 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 4 }}>
            <span style={{ fontSize: 12, fontWeight: 800, color: "#FDE68A", fontFamily: FONT }}>
              Prochain Légendaire
            </span>
            <span style={{
              fontSize: 8, fontWeight: 800, color: "#78350F",
              background: "rgba(245,158,11,.2)", borderRadius: 5, padding: "2px 6px", fontFamily: FONT,
            }}>ULTRA RARE</span>
          </div>
          <span style={{ fontSize: 11, color: "rgba(255,255,255,.5)", fontFamily: FONT }}>
            Mode Légende · Débloque tous les badges
          </span>
          <div style={{ marginTop: 7 }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 3 }}>
              <span style={{ fontSize: 9, color: "rgba(255,255,255,.3)", fontFamily: FONT }}>
                {unlockedCount}/{total} badges
              </span>
              <span style={{ fontSize: 9, color: "#FDE68A", fontWeight: 700, fontFamily: FONT }}>
                {Math.round((unlockedCount/total)*100)}%
              </span>
            </div>
            <div style={{ height: 3, background: "rgba(255,255,255,.1)", borderRadius: 2 }}>
              <div style={{
                width: `${(unlockedCount/total)*100}%`, height: "100%",
                background: "linear-gradient(90deg,#D97706,#FDE68A)", borderRadius: 2,
              }}/>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── HOME ────────────────────────────────────────────────────────────────
export default function Home(props) {
  const { profil, prog, cycleStart, setTab, premium, setPaywall, setPaywallNutrition, push, eau, setEau, weightLog, setWeightLog, lastWeighIn, setLastWeighIn, calSess, imc, obj, calObj, pObj, lObj, gObj, totR, jR, cPct, semC, getStreak, INT, MOTIVATIONS } = props;

  const goProgram = (view) => {
    try { localStorage.setItem("mc_progView", view); } catch {}
    setTab("program");
  };

  const today      = new Date();
  const todayKey   = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,"0")}-${String(today.getDate()).padStart(2,"0")}`;
  const todaySess  = calSess[todayKey];

  // ── Sommeil (loggable depuis l'Accueil, indépendant du programme) ──────────
  const todayISO = today.toISOString().split("T")[0];

  // Cible de sommeil personnalisée (National Sleep Foundation) — selon âge & sexe
  const recommendedSleep = (() => {
    const age = parseFloat(profil.age) || 30;
    let base;
    if (age < 14)      base = 9.5;
    else if (age < 18) base = 9;      // ado : 8–10h
    else if (age <= 25) base = 8;     // jeune adulte : besoin souvent plus élevé
    else if (age <= 64) base = 7.75;  // adulte : 7–9h
    else               base = 7.5;    // sénior : 7–8h
    if (profil.sexe === "femme") base += 0.25; // léger besoin supérieur documenté
    return Math.round(base * 2) / 2;  // arrondi 0,5h
  })();
  const sleepTarget = recommendedSleep;
  // On persiste la cible calculée → le score de récup / surentraînement lit la même valeur
  if (typeof window !== "undefined") {
    try {
      if (localStorage.getItem("morpho_sleep_target") !== String(sleepTarget))
        localStorage.setItem("morpho_sleep_target", String(sleepTarget));
    } catch {}
  }

  const [sleepLog, setSleepLog] = useState(() => {
    try { return JSON.parse(localStorage.getItem("morpho_sleep_log") || "{}"); } catch { return {}; }
  });
  const sleepToday = sleepLog[todayISO] ?? null;
  const logSleep = (h) => {
    const v = Math.max(0, Math.min(14, Math.round(h * 2) / 2));
    const updated = { ...sleepLog, [todayISO]: v };
    setSleepLog(updated);
    try { localStorage.setItem("morpho_sleep_log", JSON.stringify(updated)); } catch {}
  };

  const dayOfYear  = Math.floor((today - new Date(today.getFullYear(), 0, 0)) / (1000*60*60*24));
  const motiv      = MOTIVATIONS[dayOfYear % MOTIVATIONS.length];
  const streak     = getStreak;
  const tot        = totR;

  // Macros
  const consumed  = tot.cal || 0;
  const goal      = calObj || 1;
  const remaining = Math.max(goal - consumed, 0);
  const pct       = Math.min(consumed / goal, 1);
  const over      = consumed > goal;
  const r = 54, circum = 2 * Math.PI * r;

  return (
    <div className="anim" style={{ padding:"0 16px 28px" }}>

      {/* ── GREETING ─────────────────────────────────────────── */}
      <div style={{ paddingTop:24, paddingBottom:20 }}>
        <div style={{ fontSize:11.5, color:"${C.dim}",
          fontFamily:FONT, marginBottom:6 }}>
          {today.toLocaleDateString("fr-FR", { weekday:"long", day:"numeric", month:"long" })}
        </div>
        <div style={{ fontFamily:SERIF, fontSize:34, color:"${C.text}",
          letterSpacing:-1.2, lineHeight:1.05 }}>
          {profil.prenom
            ? <>Bonjour, <span style={{ fontStyle:"italic" }}>{profil.prenom}</span></>
            : <>Bonjour</>}
        </div>
        {prog && (
          <div style={{ marginTop:10, display:"flex", alignItems:"center", gap:7, flexWrap:"wrap" }}>
            <Pill color="#3B82F6" dot style={{ color:"#93C5FD", background:"rgba(59,130,246,0.10)", border:"1px solid rgba(59,130,246,0.20)" }}>
              {obj?.l} · {prog?.jours?.length||0} séances/sem.
            </Pill>
            {cycleStart && jR !== null && (
              <span style={{
                display:"inline-flex", padding:"5px 11px", borderRadius:99,
                background:"rgba(0,0,0,0.04)",
                border:"1px solid rgba(0,0,0,0.07)",
                fontSize:11.5, color:"#374151",
                fontWeight:600, fontFamily:FONT,
              }}>
                Cycle {(semC||0)+1} · J{jR}
              </span>
            )}
          </div>
        )}
      </div>

      {/* ── STREAK ───────────────────────────────────────────── */}
      {streak > 0 && (
        <Card className="pop-in" padding="none" style={{
          borderRadius:16, padding:"13px 16px",
          display:"flex", alignItems:"center", gap:11, marginBottom:12,
        }}>
          <div style={{
            width:38, height:38, borderRadius:11, fontSize:18,
            background:"rgba(248,113,113,0.10)",
            border:"1px solid rgba(248,113,113,0.18)",
            display:"grid", placeItems:"center", flexShrink:0,
          }}>🔥</div>
          <div>
            <div style={{ fontFamily:FONT, fontWeight:700, fontSize:14, color:"${C.text}" }}>
              {streak} jour{streak > 1 ? "s" : ""} de suite
            </div>
            <div style={{ fontSize:12, color:"#374151", marginTop:2, fontFamily:FONT }}>
              {streak >= 7 ? "Semaine parfaite !" : streak >= 3 ? "Continue comme ça !" : "Bonne lancée !"}
            </div>
          </div>
        </Card>
      )}

      {/* ── CITATION ─────────────────────────────────────────── */}
      <Card padding="none" style={{
        borderLeft:"3px solid #3B82F6",
        borderRadius:"0 14px 14px 0",
        padding:"13px 16px", marginBottom:12,
      }}>
        <Eyebrow color="#3B82F6" style={{ letterSpacing:"1.2px", marginBottom:5 }}>Citation du jour</Eyebrow>
        <div style={{ fontFamily:SERIF, fontStyle:"italic", fontSize:14,
          color:"#0F1923", lineHeight:1.6 }}>"{motiv}"</div>
      </Card>

      {/* ── SÉANCE DU JOUR ───────────────────────────────────── */}
      {todaySess ? (
        <Card padding="none" style={{
          background:"linear-gradient(135deg,#1E40AF 0%,#2563EB 50%,#3B82F6 100%)",
          border:"1px solid rgba(0,0,0,0.09)",
          borderRadius:20, padding:"20px 20px 18px", marginBottom:12,
          position:"relative", overflow:"hidden",
        }}>
          <div style={{ position:"absolute", top:0, left:0, right:0, height:1,
            background:"linear-gradient(90deg,transparent,rgba(0,0,0,0.12),transparent)" }}/>
          <div style={{ position:"absolute", top:-40, right:-40, width:130, height:130,
            borderRadius:"50%", background:"rgba(0,0,0,0.04)", pointerEvents:"none" }}/>
          <div style={{ display:"flex", alignItems:"center", gap:13, position:"relative" }}>
            <div style={{
              width:48, height:48, borderRadius:14,
              background:"rgba(0,0,0,0.09)",
              border:"1px solid rgba(0,0,0,0.11)",
              display:"grid", placeItems:"center", flexShrink:0,
            }}>
              <I d={ic.bolt} size={22} color="#fff" sw={2.2}/>
            </div>
            <div style={{ flex:1 }}>
              <Eyebrow color="rgba(0,0,0,0.33)" style={{ letterSpacing:"1.2px", marginBottom:3 }}>Séance du jour</Eyebrow>
              <div style={{ fontSize:18, fontWeight:700, color:"#fff",
                fontFamily:FONT, letterSpacing:-0.4 }}>{todaySess.nom}</div>
              {todaySess.intensite && (
                <div style={{ fontSize:12, color:"rgba(0,0,0,0.3)",
                  marginTop:2, fontFamily:FONT }}>
                  {INT[todaySess.intensite]?.l} · ~60 min
                </div>
              )}
            </div>
          </div>
          <button className="tap" onClick={() => goProgram("today")} style={{
            marginTop:16, width:"100%", padding:"13px",
            borderRadius:12,
            background:"rgba(0,0,0,0.08)",
            border:"1px solid rgba(0,0,0,0.12)",
            color:"#fff", display:"flex", alignItems:"center",
            justifyContent:"center", gap:8,
            fontFamily:FONT, fontSize:14, fontWeight:700, cursor:"pointer",
          }}>
            <I d={ic.play} size={13} color="#fff" sw={0} fill="#fff"/>
            Démarrer la séance
          </button>
        </Card>
      ) : !prog && (
        <Card onClick={() => goProgram("creer")} className="tap" padding="none" style={{
          borderRadius:16, padding:"16px",
          display:"flex", alignItems:"center", gap:12, marginBottom:12,
        }}>
          <div style={{ width:42, height:42, borderRadius:12,
            background:"rgba(59,130,246,0.10)",
            border:"1px solid rgba(59,130,246,0.20)",
            display:"grid", placeItems:"center", fontSize:20, flexShrink:0 }}>🏋️</div>
          <div style={{ flex:1 }}>
            <div style={{ fontSize:13.5, fontWeight:700, color:"${C.text}",
              fontFamily:FONT }}>Créer mon premier programme</div>
            <div style={{ fontSize:12, color:"#374151",
              marginTop:2, fontFamily:FONT }}>Démarre en quelques secondes</div>
          </div>
          <I d={ic.chev} size={16} color="${C.dim}"/>
        </Card>
      )}

      {/* ── ÉNERGIE DU JOUR ──────────────────────────────────── */}
      {profil.poids && profil.taille && profil.age && profil.sexe ? (
        <Card padding="none" style={{
          borderRadius:20, padding:"18px 18px 16px", marginBottom:28,
        }}>
          <div style={{ display:"flex", justifyContent:"space-between",
            alignItems:"center", marginBottom:18 }}>
            <span style={{ fontSize:16, fontWeight:700, color:"${C.text}",
              fontFamily:FONT, letterSpacing:-0.3 }}>Énergie du jour</span>
            <button className="tap" onClick={() => setTab("nutrition")} style={{
              padding:"5px 10px", background:"rgba(0,0,0,0.03)",
              border:"1px solid rgba(0,0,0,0.06)", borderRadius:8,
              color:"#374151", fontSize:11, fontFamily:FONT,
              cursor:"pointer", display:"flex", alignItems:"center", gap:3,
            }}>
              Voir <I d={ic.chev} size={11} sw={1.8}/>
            </button>
          </div>

          <div style={{ display:"flex", alignItems:"center", gap:18 }}>
            {/* Donut */}
            <div style={{ position:"relative", width:132, height:132, flexShrink:0 }}>
              <svg width="132" height="132" viewBox="0 0 132 132">
                <defs>
                  <linearGradient id="ringHome" x1="0" y1="1" x2="1" y2="0">
                    <stop offset="0%" stopColor="#2563EB"/>
                    <stop offset="100%" stopColor="#60A5FA"/>
                  </linearGradient>
                </defs>
                <g transform="rotate(-90 66 66)">
                  <circle cx="66" cy="66" r={r} fill="none"
                    stroke="rgba(0,0,0,0.05)" strokeWidth="7"/>
                  <circle cx="66" cy="66" r={r} fill="none"
                    stroke={over ? "#F87171" : "url(#ringHome)"}
                    strokeWidth="7" strokeLinecap="round"
                    strokeDasharray={circum}
                    strokeDashoffset={circum * (1 - pct)}
                    style={{ transition:"stroke-dashoffset 1s ease" }}/>
                </g>
              </svg>
              <div style={{ position:"absolute", inset:0, display:"flex",
                flexDirection:"column", alignItems:"center", justifyContent:"center" }}>
                <Eyebrow style={{ fontSize:9, letterSpacing:"1px", marginBottom:3, color:"${C.dim}" }}>
                  {over ? "Dépassé" : "Restant"}
                </Eyebrow>
                <div style={{ fontFamily:SERIF, fontSize:30,
                  color: over ? "#F87171" : "${C.text}",
                  lineHeight:1, ...NUM }}>
                  {over ? consumed - goal : remaining}
                </div>
                <div style={{ fontSize:10, color:"#374151",
                  fontFamily:FONT, marginTop:2 }}>kcal</div>
              </div>
            </div>

            {/* Macros */}
            <div style={{ flex:1, display:"flex", flexDirection:"column", gap:13 }}>
              <MacroBar label="Protéines" value={tot.p||0} goal={pObj}
                color="#3B82F6" unit="g"/>
              <MacroBar label="Glucides"  value={tot.g||0} goal={gObj}
                color="#22D3EE" unit="g"/>
              <MacroBar label="Lipides"   value={tot.l||0} goal={lObj}
                color="#34D399" unit="g"/>
            </div>
          </div>
        </Card>
      ) : (
        <Card onClick={() => setTab("profile")} className="tap" padding="none" style={{
          borderRadius:16, padding:"16px",
          display:"flex", alignItems:"center", gap:12, marginBottom:12,
        }}>
          <div style={{ width:42, height:42, borderRadius:12,
            background:"rgba(59,130,246,0.10)",
            border:"1px solid rgba(59,130,246,0.20)",
            display:"grid", placeItems:"center", fontSize:20, flexShrink:0 }}>👤</div>
          <div style={{ flex:1 }}>
            <div style={{ fontSize:13.5, fontWeight:700, color:"${C.text}",
              fontFamily:FONT }}>Compléter mon profil</div>
            <div style={{ fontSize:12, color:"#374151",
              marginTop:2, fontFamily:FONT }}>
              Pour voir tes calories et macros personnalisées
            </div>
          </div>
          <I d={ic.chev} size={16} color="${C.dim}"/>
        </Card>
      )}

      {/* ── SOMMEIL (sous l'alimentation, relié au surentraînement) ───── */}
      <Card padding="none" style={{ borderRadius:16, padding:"14px 16px", marginBottom:12,
        border: sleepToday == null ? "1px solid rgba(245,158,11,0.45)" : undefined,
        background: sleepToday == null ? "linear-gradient(160deg, rgba(245,158,11,0.06), rgba(245,158,11,0.01))" : undefined }}>
        <div style={{ display:"flex", alignItems:"center", gap:12 }}>
          <div style={{ width:42, height:42, borderRadius:12, flexShrink:0, position:"relative",
            background:"linear-gradient(145deg,#818CF8,#6366F1)",
            display:"grid", placeItems:"center",
            boxShadow:"0 4px 12px rgba(99,102,241,0.4)", fontSize:20 }}>
            😴
            {sleepToday == null && (
              <span style={{ position:"absolute", top:-3, right:-3, width:13, height:13,
                borderRadius:"50%", background:"#F59E0B", border:"2px solid #fff",
                boxShadow:"0 0 0 1px rgba(245,158,11,0.4)" }}/>
            )}
          </div>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontSize:13.5, fontWeight:700, color:C.text, fontFamily:FONT, display:"flex", alignItems:"center", gap:7 }}>
              Sommeil
              {sleepToday == null && (
                <span style={{ fontSize:9.5, fontWeight:800, letterSpacing:"0.4px",
                  color:"#B45309", background:"rgba(245,158,11,0.16)", border:"1px solid rgba(245,158,11,0.35)",
                  borderRadius:6, padding:"1px 7px", fontFamily:FONT }}>À RENSEIGNER</span>
              )}
            </div>
            <div style={{ fontSize:11.5, color: sleepToday == null ? "#B45309" : "#6B7280", marginTop:2, fontFamily:FONT }}>
              {sleepToday != null
                ? `${sleepToday} h cette nuit · cible ${sleepTarget} h`
                : `Tu n'as pas encore noté ta nuit · cible ${sleepTarget} h`}
            </div>
            <div style={{ fontSize:10, color:"#9CA3AF", marginTop:3, fontFamily:FONT, lineHeight:1.35 }}>
              Cible adaptée à ton âge{profil.age ? ` (${parseInt(profil.age,10)} ans)` : ""}{profil.sexe === "femme" ? " et à ton sexe" : ""} — National Sleep Foundation
            </div>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:6, flexShrink:0 }}>
            <button className="tap" aria-label="Moins"
              onClick={() => logSleep((sleepToday ?? sleepTarget) - 0.5)}
              style={{ width:30, height:30, borderRadius:9, cursor:"pointer",
                background:"rgba(99,102,241,0.10)", border:"1px solid rgba(99,102,241,0.25)",
                color:"#6366F1", fontSize:18, fontWeight:700, fontFamily:FONT,
                display:"grid", placeItems:"center", lineHeight:1 }}>−</button>
            <div style={{ minWidth:46, textAlign:"center" }}>
              <span style={{ fontFamily:FONT, fontSize:18, fontWeight:800, color:C.text, ...NUM }}>
                {sleepToday != null ? sleepToday : "—"}
              </span>
              <span style={{ fontSize:11, color:"#9CA3AF", marginLeft:1 }}>h</span>
            </div>
            <button className="tap" aria-label="Plus"
              onClick={() => logSleep((sleepToday ?? (sleepTarget - 0.5)) + 0.5)}
              style={{ width:30, height:30, borderRadius:9, cursor:"pointer",
                background:"linear-gradient(145deg,#818CF8,#6366F1)", border:"1px solid rgba(99,102,241,0.5)",
                color:"#fff", fontSize:18, fontWeight:700, fontFamily:FONT,
                boxShadow:"0 2px 8px rgba(99,102,241,0.4)",
                display:"grid", placeItems:"center", lineHeight:1 }}>+</button>
          </div>
        </div>
      </Card>


      {/* ── BADGES ──────────────────────────────────────────── */}
      <BadgeSection FONT={FONT} />

      <div style={{ marginBottom:8 }}>
        <div style={{ marginBottom:5 }}>
          <Eyebrow style={{ fontSize:11, letterSpacing:"0.09em", marginBottom:4 }}>Passer au niveau supérieur</Eyebrow>
          <div style={{ fontSize:22, fontWeight:700, color:"${C.text}",
            fontFamily:FONT, letterSpacing:-0.6, marginBottom:14 }}>Mes programmes</div>
        </div>

        <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
          <PackCard type="training"  onUnlock={() => setPaywall(true)}/>
          <PackCard type="nutrition" onUnlock={() => setPaywallNutrition(true)}/>
        </div>
      </div>

    </div>
  );
}
